pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PoCGame c;

    function setUp() public {
        vm.prank(address(this), address(this));
        c = new PoCGame(address(this), 0);
    }

    function _run(uint256 amount) internal {
        vm.assume(true);
        uint256 diffBefore;
        try c.currentDifficulty() returns (uint256 __r) { diffBefore = __r; } catch { return; }
        try c.AdjustDifficulty(amount) {} catch { return; }
        uint256 diffAfter;
        try c.currentDifficulty() returns (uint256 __r) { diffAfter = __r; } catch { return; }
        assertTrue(amount == 0 || diffAfter != diffBefore);
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
